parameters.text:
=Tu es le directeur marketing de la marque {{$json.brand}}.

Crée un kit commercial multicanal pour ce produit :
- Nom : {{$json.product_name}}
- Type : {{$json.product_type}}
- Client cible : {{$json.target_customer}}
- Bénéfice principal : {{$json.main_benefit}}
- Fonctionnalités : {{$json.features}}
- Prix : {{$json.price_eur}} €
- Langue : {{$json.language}}
- Ton : {{$json.tone}}

RÈGLES IMPÉRATIVES
1. Réponds uniquement avec un objet JSON valide, sans balises Markdown, sans commentaire avant ou après.
2. N'invente aucune fonctionnalité non fournie.
3. N'utilise aucune promesse médicale, juridique ou financière.
4. Le titre Etsy doit rester lisible, naturel et inférieur ou égal à 140 caractères.
5. Fournis exactement 13 tags Etsy, chacun inférieur ou égal à 20 caractères.
6. Les hashtags ne doivent pas contenir d'espaces.
7. Le contenu doit être adapté à une audience francophone.
8. N'utilise pas de formulations culpabilisantes envers les parents séparés.

SCHÉMA JSON OBLIGATOIRE
{
  "product": {
    "name": "string",
    "price_eur": 0,
    "audience": "string",
    "positioning": "string"
  },
  "etsy": {
    "title": "string",
    "description": "string",
    "tags": ["13 chaînes exactement"],
    "short_benefits": ["3 à 5 chaînes"],
    "faq": [
      {"question": "string", "answer": "string"}
    ],
    "suggested_price_eur": 0,
    "launch_promo": "string"
  },
  "pinterest": {
    "pins": [
      {"title": "string", "description": "string", "visual_hook": "string"}
    ]
  },
  "instagram": {
    "caption": "string",
    "carousel_slides": ["5 à 7 chaînes"],
    "hashtags": ["8 à 15 chaînes"]
  },
  "tiktok": {
    "hook": "string",
    "script_30s": "string",
    "shots": ["5 à 8 chaînes"],
    "caption": "string",
    "hashtags": ["5 à 8 chaînes"]
  },
  "email": {
    "subject": "string",
    "preheader": "string",
    "body": "string",
    "cta": "string"
  },
  "visuals": {
    "etsy_image_texts": ["7 à 10 chaînes"],
    "image_generation_prompts": ["3 chaînes"]
  },
  "quality_control": {
    "claims_to_verify": ["chaînes"],
    "missing_information": ["chaînes"],
    "human_validation_required": true
  }
}

parameters.jsCode:
const raw = $json.output ?? $json.text ?? $json.response ?? '';

function stripCodeFence(value) {
  return String(value)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

let parsed;
try {
  parsed = JSON.parse(stripCodeFence(raw));
} catch (error) {
  throw new Error(
    'La réponse IA n’est pas un JSON valide. Relancez le workflow ou réduisez le contenu du produit. Détail : ' +
    error.message
  );
}

const errors = [];
const requiredSections = ['product', 'etsy', 'pinterest', 'instagram', 'tiktok', 'email', 'visuals', 'quality_control'];
for (const section of requiredSections) {
  if (!parsed[section] || typeof parsed[section] !== 'object') {
    errors.push(`Section manquante ou invalide : ${section}`);
  }
}

if (!parsed.etsy?.title || parsed.etsy.title.length > 140) {
  errors.push('Le titre Etsy est absent ou dépasse 140 caractères.');
}

if (!Array.isArray(parsed.etsy?.tags) || parsed.etsy.tags.length !== 13) {
  errors.push('La liste Etsy doit contenir exactement 13 tags.');
} else {
  parsed.etsy.tags.forEach((tag, index) => {
    if (typeof tag !== 'string' || tag.length > 20) {
      errors.push(`Tag Etsy ${index + 1} invalide ou supérieur à 20 caractères.`);
    }
  });
}

if (!Array.isArray(parsed.pinterest?.pins) || parsed.pinterest.pins.length < 3) {
  errors.push('Au moins 3 épingles Pinterest sont attendues.');
}

if (parsed.quality_control?.human_validation_required !== true) {
  errors.push('La validation humaine doit rester obligatoire.');
}

return [{
  json: {
    status: errors.length === 0 ? 'READY_FOR_HUMAN_REVIEW' : 'NEEDS_CORRECTION',
    validation_errors: errors,
    generated_at: new Date().toISOString(),
    marketing_package: parsed
  }
}];
